#include <bits/stdc++.h>
using namespace std;

const int MAX_LIMIT = 510;

int m_value, n_value, mod_value;

inline int sum_modulo(int a, int b) { return (a + b) % mod_value; }
inline int diff_modulo(int a, int b) { return a - b < 0 ? a - b + mod_value : a - b; }
inline int prod_modulo(int a, int b) { return (long long) a * b % mod_value; }

int factorials[MAX_LIMIT], inv_factorials[MAX_LIMIT], inverses[MAX_LIMIT];

void prepare_factorials(int limit)
{
    factorials[0] = 1; inverses[1] = 1; factorials[1] = 1; inv_factorials[0] = 1; inv_factorials[1] = 1;
    for (int i = 2; i <= limit; i++) inverses[i] = prod_modulo((mod_value - mod_value / i), inverses[mod_value % i]);
    for (int i = 2; i <= limit; i++) { factorials[i] = prod_modulo(factorials[i - 1], i); inv_factorials[i] = prod_modulo(inv_factorials[i - 1], inverses[i]); }
}

int choose(int n, int r) {
    if (n < r || r < 0) return 0;
    return prod_modulo(prod_modulo(factorials[n], inv_factorials[r]), inv_factorials[n - r]);
}

int arrangements(int n, int r) {
    return choose(n + r - 1, r - 1);
}

int f_vals[MAX_LIMIT], g_vals[MAX_LIMIT], prefix_sums[MAX_LIMIT];
int f_table[MAX_LIMIT][MAX_LIMIT], g_table[MAX_LIMIT][MAX_LIMIT];

int main()
{
    scanf("%d %d %d", &n_value, &m_value, &mod_value);
    prepare_factorials(500);
    for (int i = 1; i <= n_value; i++) prefix_sums[i] = sum_modulo(prefix_sums[i - 1], i);
    f_vals[0] = 1; f_vals[1] = 2;
    g_vals[0] = 0; g_vals[1] = 0;
    for (int i = 2; i <= n_value; i++)
    {
        for (int j = 0; j < i; j++)
        {
            int temp = prod_modulo(choose(i - 1, j), prod_modulo(f_vals[j], f_vals[i - 1 - j]));
            f_vals[i] = sum_modulo(f_vals[i], prod_modulo(temp, i + 1));
            g_vals[i] = sum_modulo(g_vals[i], prod_modulo(temp, prefix_sums[j] + prefix_sums[i - 1 - j]));
            int temp2 = prod_modulo(add_modulo(mul_modulo(g_vals[j], f_vals[i - 1 - j]), mul_modulo(g_vals[i - 1 - j], f_vals[j])), i + 1);
            g_vals[i] = sum_modulo(g_vals[i], prod_modulo(temp2, choose(i - 1, j)));
        }
    }
    f_table[0][0] = 1; g_table[0][0] = 0;
    for (int i = 0; i <= m_value; i++)
        for (int j = 0; j <= m_value; j++)
        {
            if (f_table[i][j] == 0) continue;
            for (int k = 1; k + j <= m_value; k++)
            {
                f_table[i + 1][j + k] = sum_modulo(f_table[i + 1][j + k], prod_modulo(prod_modulo(f_table[i][j], f_vals[k]), choose(j + k, k)));
                g_table[i + 1][j + k] = sum_modulo(g_table[i + 1][j + k], prod_modulo(add_modulo(mul_modulo(g_table[i][j], f_vals[k]), mul_modulo(f_table[i][j], g_vals[k])), choose(j + k, k)));
            }
        }
    int answer_final = 0;
    for (int i = 1; i <= m_value; i++)
        if (n_value + 1 - m_value >= i)
            answer_final = sum_modulo(answer_final, prod_modulo(g_table[i][m_value], arrangements(n_value + 1 - m_value - i, i + 1)));
    printf("%d\n", answer_final);
    return 0;
}
